package com.print.kiosk.service.impl;

import com.print.kiosk.dto.request.*;
import com.print.kiosk.dto.response.*;
import com.print.kiosk.entity.*;
import com.print.kiosk.exception.*;
import com.print.kiosk.repository.*;
import com.print.kiosk.service.interfaces.RequestProcessingService;
import com.print.kiosk.service.model.FileDownloadPayload;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

@Service
public class RequestProcessingServiceImpl implements RequestProcessingService{
    private static final ZoneId DHAKA=ZoneId.of("Asia/Dhaka");
    private final PrintRequestRepository requests; private final PrintRequestFileRepository files; private final UserAccountRepository accounts; private final RequestClaimRepository claims; private final RequestExceptionRepository exceptions; private final FileDownloadEventRepository downloads; private final PrintRequestStatusHistoryRepository history; private final long deletionHours; private final long expirationHours;
    public RequestProcessingServiceImpl(PrintRequestRepository r,PrintRequestFileRepository f,UserAccountRepository a,RequestClaimRepository c,RequestExceptionRepository e,FileDownloadEventRepository d,PrintRequestStatusHistoryRepository h,@Value("${app.print-request.file-deletion-delay-hours:24}")long deletionHours,@Value("${app.print-request.expiration-hours:12}")long expirationHours){requests=r;files=f;accounts=a;claims=c;exceptions=e;downloads=d;history=h;this.deletionHours=deletionHours;this.expirationHours=expirationHours;}
    @Transactional public RequestActionResponse claimNext(Long agentId){UserAccount agent=agent(agentId);if(claims.existsByAgent_IdAndActiveTrue(agentId))throw new InvalidQueueActionException("This agent already has an active request claim");List<PrintRequest> list=requests.findNextPaidAvailableForClaim(PageRequest.of(0,1));if(list.isEmpty())throw new ResourceNotFoundException("No paid request is currently available for processing");PrintRequest r=list.get(0);LocalDateTime now=LocalDateTime.now(DHAKA);PrintRequestStatus old=r.getStatus();r.setStatus(PrintRequestStatus.CLAIMED);r.setAssignedAgent(agent);r.setClaimedAt(now);r.setClaimLastActivityAt(now);requests.saveAndFlush(r);RequestClaim c=new RequestClaim();c.setPrintRequest(r);c.setAgent(agent);claims.save(c);record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,"Claimed for processing");return action(r,"Request claimed successfully");}
    @Transactional(readOnly=true) public ProcessingRequestResponse getDetails(Long requestId,Long agentId){PrintRequest r=requests.findById(requestId).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));assertAssigned(r,agentId);return details(r);}
    @Transactional public FileDownloadPayload downloadFile(Long requestId,Long fileId,Long agentId,String clientIp){PrintRequest r=requests.findByIdForUpdate(requestId).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));assertAssignedAndState(r,agentId,Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING,PrintRequestStatus.PRINTING));PrintRequestFile file=files.findByIdAndRequestId(fileId,requestId).orElseThrow(()->new ResourceNotFoundException("Print file was not found"));if(file.getFileData()==null||file.getBinaryDeletedAt()!=null)throw new FileAlreadyDeletedException("The stored file content has already been deleted");LocalDateTime now=LocalDateTime.now(DHAKA);if(r.getStatus()==PrintRequestStatus.CLAIMED){PrintRequestStatus old=r.getStatus();r.setStatus(PrintRequestStatus.DOWNLOADING);record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,"File download started");}touch(r,now);FileDownloadEvent event=new FileDownloadEvent();event.setPrintRequest(r);event.setPrintRequestFile(file);event.setAgent(r.getAssignedAgent());event.setByteCount(file.getFileData().length);event.setClientIp(clientIp);downloads.save(event);requests.save(r);return new FileDownloadPayload(file.getOriginalFileName(),file.getMimeType(),file.getFileData());}
    @Transactional public RequestActionResponse startPrinting(Long requestId,Long agentId){PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.DOWNLOADING));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(PrintRequestStatus.PRINTING);r.setPrintingStartedAt(now);touch(r,now);record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,"Printing started");return action(requests.save(r),"Printing started");}
    @Transactional public RequestActionResponse complete(Long requestId,Long agentId,CompletePrintingRequest request){if(!request.isConfirmed())throw new InvalidQueueActionException("Completion must be explicitly confirmed");PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.PRINTING));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(PrintRequestStatus.COMPLETED);r.setCompletedAt(now);r.setClaimLastActivityAt(now);closeClaim(r,ClaimReleaseReason.COMPLETED,"Printing completed",now);files.markDeletionEligibleByRequestId(r.getId(),now.plusHours(deletionHours));record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,"Printing completed");return action(requests.save(r),"Request completed successfully");}
    @Transactional public RequestActionResponse release(Long requestId,Long agentId,ReleaseClaimRequest request){PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);closeClaim(r,ClaimReleaseReason.MANUAL,request.getReason().trim(),now);clearClaim(r);r.setStatus(PrintRequestStatus.PAID);record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,request.getReason().trim());return action(requests.save(r),"Claim released");}
    @Transactional public RequestActionResponse pause(Long requestId,Long agentId,PauseRequestRequest request){PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING,PrintRequestStatus.PRINTING));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(PrintRequestStatus.PAUSED);r.setPausedAt(now);closeClaim(r,ClaimReleaseReason.PAUSED,request.getReason().trim(),now);createException(r,r.getAssignedAgent(),RequestExceptionType.OTHER,request.getReason(),old,r.getStatus());record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,request.getReason().trim());return action(requests.save(r),"Request paused and moved to the exception queue");}
    @Transactional public RequestActionResponse reportProblem(Long requestId,Long agentId,ReportProblemRequest request){PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING,PrintRequestStatus.PRINTING));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(PrintRequestStatus.FILE_ERROR);closeClaim(r,ClaimReleaseReason.FILE_ERROR,request.getReason().trim(),now);createException(r,r.getAssignedAgent(),request.getExceptionType(),request.getReason(),old,r.getStatus());record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,request.getReason().trim());return action(requests.save(r),"Problem recorded and request moved to the exception queue");}
    @Transactional public RequestActionResponse cancel(Long requestId,Long agentId,CancelProcessingRequest request){PrintRequest r=lockedAssigned(requestId,agentId,Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING,PrintRequestStatus.PRINTING,PrintRequestStatus.PAUSED,PrintRequestStatus.FILE_ERROR));PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(PrintRequestStatus.CANCELLED);r.setCancelledAt(now);r.setCancellationReason(request.getReason().trim());closeClaimIfPresent(r,ClaimReleaseReason.CANCELLED,request.getReason(),now);files.markDeletionEligibleByRequestId(r.getId(),now.plusHours(deletionHours));record(r,old,r.getStatus(),StatusActorType.AGENT,agentId,request.getReason().trim());return action(requests.save(r),"Request cancelled. Existing payment remains recorded; no refund was created.");}
    @Transactional public RequestActionResponse reopenByAgent(Long requestId,Long agentId,ReopenRequestRequest request){PrintRequest r=requests.findByIdForUpdate(requestId).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));assertAssigned(r,agentId);return reopen(r,agentId,StatusActorType.AGENT,request.getReason());}
    @Transactional public RequestActionResponse reopenByAdmin(Long requestId,Long adminId,ReopenRequestRequest request){accounts.findById(adminId).orElseThrow(()->new ResourceNotFoundException("Administrator account was not found"));PrintRequest r=requests.findByIdForUpdate(requestId).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));return reopen(r,adminId,StatusActorType.ADMIN,request.getReason());}
    private RequestActionResponse reopen(PrintRequest r,Long actor,StatusActorType type,String reason){if(!Set.of(PrintRequestStatus.COMPLETED,PrintRequestStatus.CANCELLED,PrintRequestStatus.PAUSED,PrintRequestStatus.FILE_ERROR).contains(r.getStatus()))throw new InvalidQueueActionException("Only completed, cancelled, paused, or file-error requests may be reopened");if(files.existsByPrintRequest_IdAndFileDataIsNull(r.getId()))throw new FileAlreadyDeletedException("This request cannot be reopened because file content has been deleted");PrintRequestStatus old=r.getStatus();LocalDateTime now=LocalDateTime.now(DHAKA);r.setStatus(r.getPaymentStatus()==PaymentStatus.PAID?PrintRequestStatus.PAID:PrintRequestStatus.AWAITING_PAYMENT);if(r.getPaymentStatus()!=PaymentStatus.PAID)r.setExpiresAt(now.plusHours(expirationHours));r.setAssignedAgent(null);clearClaim(r);r.setCompletedAt(null);r.setPausedAt(null);r.setCancelledAt(null);r.setCancellationReason(null);r.setReopenedAt(now);files.clearDeletionEligibilityByRequestId(r.getId());for(RequestException e:exceptions.findByPrintRequest_IdAndResolvedAtIsNull(r.getId())){e.setResolvedAt(now);e.setResolvedByAccountId(actor);e.setResolutionNote(reason.trim());exceptions.save(e);}record(r,old,r.getStatus(),type,actor,reason.trim());return action(requests.save(r),"Request reopened successfully");}
    private UserAccount agent(Long id){UserAccount a=accounts.findById(id).orElseThrow(()->new ResourceNotFoundException("Agent account was not found"));if(a.getRole()!=AccountRole.AGENT||a.getAgentStatus()!=AgentStatus.APPROVED)throw new UnauthorizedRequestOperationException("Only an approved agent may process requests");return a;}
    private PrintRequest lockedAssigned(Long id,Long agentId,Set<PrintRequestStatus> states){PrintRequest r=requests.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException("Print request was not found"));assertAssignedAndState(r,agentId,states);return r;}
    private void assertAssigned(PrintRequest r,Long agentId){if(r.getAssignedAgent()==null||!r.getAssignedAgent().getId().equals(agentId))throw new UnauthorizedRequestOperationException("Only the assigned agent may operate this request");}
    private void assertAssignedAndState(PrintRequest r,Long agentId,Set<PrintRequestStatus> states){assertAssigned(r,agentId);if(!states.contains(r.getStatus()))throw new InvalidQueueActionException("This action is not allowed while the request status is "+r.getStatus());}
    private void touch(PrintRequest r,LocalDateTime now){r.setClaimLastActivityAt(now);claims.findActiveByRequestIdForUpdate(r.getId()).ifPresent(c->{c.setLastActivityAt(now);claims.save(c);});}
    private void closeClaim(PrintRequest r,ClaimReleaseReason reason,String note,LocalDateTime now){RequestClaim c=claims.findActiveByRequestIdForUpdate(r.getId()).orElseThrow(()->new InvalidQueueActionException("No active claim exists for this request"));c.setActive(false);c.setReleasedAt(now);c.setReleaseReason(reason);c.setReleaseNote(note);c.setLastActivityAt(now);claims.save(c);}
    private void closeClaimIfPresent(PrintRequest r,ClaimReleaseReason reason,String note,LocalDateTime now){claims.findActiveByRequestIdForUpdate(r.getId()).ifPresent(c->{c.setActive(false);c.setReleasedAt(now);c.setReleaseReason(reason);c.setReleaseNote(note);c.setLastActivityAt(now);claims.save(c);});}
    private void clearClaim(PrintRequest r){r.setAssignedAgent(null);r.setClaimedAt(null);r.setClaimLastActivityAt(null);r.setPrintingStartedAt(null);}
    private void createException(PrintRequest r,UserAccount agent,RequestExceptionType type,String reason,PrintRequestStatus old,PrintRequestStatus next){RequestException e=new RequestException();e.setPrintRequest(r);e.setAgent(agent);e.setExceptionType(type);e.setReason(reason.trim());e.setPreviousStatus(old);e.setNewStatus(next);exceptions.save(e);}
    private void record(PrintRequest r,PrintRequestStatus old,PrintRequestStatus next,StatusActorType actorType,Long actorId,String reason){PrintRequestStatusHistory h=new PrintRequestStatusHistory();h.setPrintRequest(r);h.setPreviousStatus(old);h.setNewStatus(next);h.setActorType(actorType);h.setActorAccountId(actorId);h.setReason(reason);history.save(h);}
    private RequestActionResponse action(PrintRequest r,String message){UserAccount a=r.getAssignedAgent();return new RequestActionResponse(r.getId(),r.getTrackingNumber(),r.getStatus(),r.getPaymentStatus(),a==null?null:a.getId(),a==null?null:a.getAgentId(),LocalDateTime.now(DHAKA),message);}
    private ProcessingRequestResponse details(PrintRequest r){List<ProcessingFileResponse> fs=files.findByPrintRequest_IdOrderByIdAsc(r.getId()).stream().map(f->new ProcessingFileResponse(f.getId(),f.getOriginalFileName(),f.getFileType(),f.getMimeType(),f.getFileSizeBytes(),f.getPageCount(),f.getPhysicalSheetsPerCopy(),f.getTotalPhysicalSheets(),f.getCopies(),f.getSubtotal(),f.getFileData()!=null&&f.getBinaryDeletedAt()==null)).toList();UserAccount a=r.getAssignedAgent();return new ProcessingRequestResponse(r.getId(),r.getTrackingNumber(),r.getFullName(),r.getRegistrationNumber(),r.getUserType(),r.getDepartment(),r.getPaymentStatus(),r.getStatus(),r.getPrintColor(),r.getPrintingSide(),r.getCopies(),r.getTotalDocumentPages(),r.getTotalPhysicalSheets(),r.getAppliedRate(),r.getTotalAmount(),a==null?null:a.getId(),a==null?null:a.getAgentId(),r.getClaimedAt(),r.getPrintingStartedAt(),r.getCompletedAt(),fs);}
}